CREATE TYPE "CustomerType" AS ENUM ('CREDIT', 'FLEET');
CREATE TYPE "CustomerLedgerType" AS ENUM ('SALE', 'RECEIPT', 'ADJUSTMENT');
ALTER TABLE "sales" ADD COLUMN "customer_id" TEXT, ADD COLUMN "vehicle_id" TEXT;
CREATE TABLE "customers" ("id" TEXT NOT NULL,"organization_id" TEXT NOT NULL,"name" TEXT NOT NULL,"code" TEXT NOT NULL,"type" "CustomerType" NOT NULL DEFAULT 'CREDIT',"phone" TEXT,"email" TEXT,"tax_id" TEXT,"billing_address" TEXT,"credit_limit" DECIMAL(14,2) NOT NULL DEFAULT 0,"credit_days" INTEGER NOT NULL DEFAULT 0,"active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "customers_pkey" PRIMARY KEY ("id"));
CREATE TABLE "vehicles" ("id" TEXT NOT NULL,"customer_id" TEXT NOT NULL,"number" TEXT NOT NULL,"label" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "vehicles_pkey" PRIMARY KEY ("id"));
CREATE TABLE "customer_receipts" ("id" TEXT NOT NULL,"organization_id" TEXT NOT NULL,"station_id" TEXT NOT NULL,"customer_id" TEXT NOT NULL,"amount" DECIMAL(14,2) NOT NULL,"payment_method" "PaymentMethod" NOT NULL,"reference_no" TEXT,"notes" TEXT,"received_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"created_by_id" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "customer_receipts_pkey" PRIMARY KEY ("id"));
CREATE TABLE "customer_ledger" ("id" TEXT NOT NULL,"organization_id" TEXT NOT NULL,"station_id" TEXT NOT NULL,"customer_id" TEXT NOT NULL,"type" "CustomerLedgerType" NOT NULL,"amount" DECIMAL(14,2) NOT NULL,"sale_id" TEXT,"receipt_id" TEXT,"description" TEXT NOT NULL,"due_date" TIMESTAMP(3),"occurred_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"created_by_id" TEXT NOT NULL,CONSTRAINT "customer_ledger_pkey" PRIMARY KEY ("id"));
CREATE INDEX "customers_organization_id_active_idx" ON "customers"("organization_id", "active");
CREATE UNIQUE INDEX "customers_organization_id_code_key" ON "customers"("organization_id", "code");
