CREATE UNIQUE INDEX "customer_ledger_sale_id_key" ON "customer_ledger"("sale_id");
CREATE UNIQUE INDEX "customer_ledger_receipt_id_key" ON "customer_ledger"("receipt_id");
CREATE INDEX "customer_ledger_customer_id_occurred_at_idx" ON "customer_ledger"("customer_id", "occurred_at");
CREATE INDEX "customer_ledger_customer_id_due_date_idx" ON "customer_ledger"("customer_id", "due_date");
CREATE INDEX "sales_customer_id_occurred_at_idx" ON "sales"("customer_id", "occurred_at");
